"""T21 suite M (pre-registration L672): minimal pairs for presence. 12 condition kinds x 2 magnitudes = 24 base items reporting a change that already happened; each gets 4 one-element edits (F forecast, P plan or intent, W warning, S single small local event) plus 24 neutral items (N). Deterministic templates, no model. Writes runs/pulse/suiteM/items.jsonl {id, text, kind, mag, var}. python3 build_suite_m.py"""
import json
T = {
 "prices":   ("Food prices rose {n}% across the country in {m}. The statistics office said it was the steepest rise in {y} years.", "Food prices are expected to rise {n}% across the country next year. Economists said it would be the steepest rise in {y} years.", "The government plans a review of food price rules across the country. Officials said work will begin next month.", "Officials warned that food prices could rise {n}% across the country. The statistics office said the risk is the highest in {y} years.", "A bakery in one town raised the price of a loaf by 10 pence in {m}. The owner said flour had become dearer."),
 "jobs":     ("Unemployment rose to {n}% in {m}, the labour ministry said. About {k} thousand jobs were lost nationwide.", "Unemployment is forecast to rise to {n}% next year, the labour ministry said. About {k} thousand jobs are expected to go nationwide.", "The labour ministry plans a review of job support schemes nationwide. Officials said talks will start next month.", "The labour ministry warned that unemployment could rise to {n}%. About {k} thousand jobs are at risk nationwide.", "A workshop in one town laid off 12 workers in {m}. The owner blamed weak orders."),
 "fuel":     ("Petrol prices jumped {n}% nationwide in {m}. Filling stations reported queues in several regions.", "Petrol prices are expected to jump {n}% nationwide next month. Analysts said queues are likely in several regions.", "The energy agency plans talks with fuel importers about supply. Officials said the talks start next week.", "Fuel suppliers warned that petrol prices could jump {n}% nationwide. Analysts said queues are possible in several regions.", "One filling station in a village ran out of diesel for a day in {m}."),
 "hunger":   ("Hunger spread across the northern region in {m}: {k} thousand families now lack enough food, aid agencies reported.", "Aid agencies expect hunger to spread across the northern region: {k} thousand families may lack enough food by spring.", "Aid agencies plan a food survey across the northern region. Staff said fieldwork begins next month.", "Aid agencies warned that hunger could spread across the northern region, putting {k} thousand families at risk.", "A food bank in one town gave out its last parcels on Friday."),
 "air":      ("Air pollution rose sharply across the capital in {m}; monitors showed smog at {n} times the safe limit.", "Air pollution is forecast to rise sharply across the capital next month; smog may reach {n} times the safe limit.", "The city plans a review of its air monitoring network. Officials said the review will take a year.", "Officials warned that smog could reach {n} times the safe limit across the capital next month.", "A factory chimney in one neighbourhood released thick smoke for an hour on Tuesday."),
 "disease":  ("Cholera cases rose to {k} thousand in {m}, health officials said. Hospitals in three provinces are full.", "Health officials expect cholera cases to reach {k} thousand by next month. Hospitals in three provinces may fill up.", "Health officials plan a vaccination drive in three provinces. The drive is due to start next quarter.", "Health officials warned that cholera cases could reach {k} thousand. Hospitals in three provinces could fill up.", "A clinic in one village treated five cholera patients on Monday."),
 "unrest":   ("Protests spread across {k} cities in {m}, with police reporting clashes and road closures nationwide.", "Protests are expected to spread across {k} cities next month, organisers said, with road closures likely nationwide.", "Organisers plan a march in the capital next month. They said they have asked the city for a route.", "Police warned that protests across {k} cities could turn violent next month, with road closures possible nationwide.", "About twenty people protested outside a town hall on Monday."),
 "housing":  ("Average rents rose {n}% nationwide in {m}, the housing agency said. It was the biggest annual rise on record.", "Average rents are projected to rise {n}% nationwide next year, the housing agency said. It would be the biggest annual rise on record.", "The housing agency plans a review of rent rules nationwide. A report is due next year.", "The housing agency warned that average rents could rise {n}% nationwide next year.", "One landlord in a small town raised the rent on a flat by 50 pounds in {m}."),
 "credit":   ("The central bank raised its key interest rate to {n}% in {m}. Mortgage rates followed across the country.", "The central bank is expected to raise its key interest rate to {n}% next month. Mortgage rates would follow across the country.", "The central bank plans to review its rate framework. Officials said a paper will be published next year.", "The central bank warned that its key interest rate could rise to {n}%. Mortgage rates could follow across the country.", "A credit union in one town raised its car loan rate by half a point in {m}."),
 "water":    ("Reservoirs fell to {n}% of capacity in {m}, and {k} cities introduced water rationing.", "Reservoirs are forecast to fall to {n}% of capacity, and {k} cities may need water rationing.", "The water agency plans a review of reservoir management. Officials said public meetings begin next month.", "The water agency warned that reservoirs could fall to {n}% of capacity, and {k} cities may need rationing.", "One village well ran dry for a week in {m}."),
 "cyber":    ("A cyberattack shut down hospital and bank systems across the country in {m}. Services stayed offline for days.", "Officials expect cyberattacks on hospital and bank systems across the country next month. Services may go offline for days.", "The government plans a cyber security review of hospital and bank systems. A report is due next year.", "Officials warned that cyberattacks could shut down hospital and bank systems across the country.", "A small shop's website was hacked for a day in {m}."),
 "roads":    ("A bridge collapse and flooding closed major roads and rail lines across the region in {m}, cutting off {k} towns.", "Engineers expect flooding to close major roads and rail lines across the region next month, cutting off {k} towns.", "The transport agency plans to inspect bridges across the region. Inspections start next year.", "Engineers warned that flooding could close major roads and rail lines across the region, cutting off {k} towns.", "A pothole closed one lane of a village road for a day in {m}."),
}
NEUTRAL = ["The local football club beat its rivals 3-1 in the cup final on Saturday. Fans celebrated in the town square.", "A new exhibition of landscape paintings opens at the city museum this week.", "The author's latest novel tops the bestseller list for a third week.", "The orchestra announced its programme for the coming season, including two premieres.", "A film festival will screen 40 documentaries over ten days in the capital.", "The chess champion defended her title after a tense final game.", "The university named a new head of the music department.", "A popular bakery chain opened its tenth branch in the city centre.", "The tennis star said she will retire after the next tournament.", "Zoo keepers welcomed a baby giraffe, the first born there in six years.", "The mayor cut the ribbon on a new public library in the east of town.", "A local choir won first prize at the regional singing competition.", "The theatre company staged a sold-out revival of a classic comedy.", "Cyclists took part in a charity ride through the countryside on Sunday.", "The museum returned a famous painting to its owners after a long loan.", "A chef opened a restaurant serving dishes from five regions.", "The rugby team signed a new coach on a three-year deal.", "The botanical garden unveiled a new glasshouse for tropical plants.", "A poet won the national prize for her collection about the sea.", "The marathon drew 20 thousand runners on a sunny morning.", "The band announced a reunion tour with 30 dates.", "A school choir performed at the national day concert.", "The city's old clock tower reopened after careful restoration.", "A famous violinist gave a free concert in the park."]
MAG = {1: dict(n=14, k=250, y=10), 2: dict(n=4, k=30, y=2)}; MONTHS = ["October", "September", "August", "November"]; out = []
for ki, (kind, tpl) in enumerate(T.items()):
    for mag in (1, 2):
        m = MONTHS[(ki + mag) % 4]
        for var, t in zip("BFPWS", tpl): out.append({"id": f"M-{kind}-{mag}-{var}", "text": t.format(m=m, **MAG[mag]), "kind": kind, "mag": mag, "var": var})
for i, t in enumerate(NEUTRAL): out.append({"id": f"M-neutral-{i}-N", "text": t, "kind": "neutral", "mag": 0, "var": "N"})
with open("runs/pulse/suiteM/items.jsonl", "w") as f:
    for r in out: f.write(json.dumps(r) + "\n")
import collections; print(len(out), "items", dict(collections.Counter(r["var"] for r in out)))
